#!/bin/bash
# zynthian package script for the @@NAME@@ zynthian widget (zynthian-packages: @@CATEGORY@@/@@PACKAGE@@).
# A widget UI bundle (zyngui:widget extension bundle, no binaries) for the LV2 plugin <@@PLUGIN_URI@@>.
# Installs the bundle from the latest v* tag of its repository into lv2-widgets. webconf offers an update when a
# newer v* tag is pushed: new versions don't need changes here.
# Generated by the zynthian-lv2-plugin skill.

GITHUB="@@GITHUB@@"
DIRNAME="@@BUNDLE@@"

REPO_URL="https://github.com/$GITHUB.git"
DST_DIR="${ZYNTHIAN_PLUGINS_DIR:-/zynthian/zynthian-plugins}/lv2-widgets"
STAMP="${ZYNTHIAN_CONFIG_DIR:-/zynthian/config}/lv2.stamp"

# Version = newest v* tag (webconf offers an update when it changes)
git_version() {
    git ls-remote --tags --refs "$REPO_URL" 'v*' | awk -F/ '{ print $3 }' | sort -V | tail -1
}

do_install() {
    set -ex
    tag="$(git_version)"
    [ -n "$tag" ] || { echo "no v* tag in $REPO_URL"; exit 1; }
    tmp="$(mktemp -d)"
    wget -q -O- "https://github.com/$GITHUB/archive/refs/tags/$tag.tar.gz" | tar xz -C "$tmp"
    mkdir -p "$DST_DIR"
    rm -rf "$DST_DIR/$DIRNAME"
    mv "$tmp"/*/"$DIRNAME" "$DST_DIR/"
    rm -rf "$tmp"
    touch "$STAMP"
    set +x
    echo "installed"
}

do_uninstall() {
    if [[ $(is_installed) == "installed" ]]; then
        rm -rf "$DST_DIR/$DIRNAME"
        touch "$STAMP"
        echo "uninstalled"
    else
        echo "not installed"
    fi
}

is_installed() {
    if [[ -d "$DST_DIR/$DIRNAME" ]]; then
        echo "installed"
    else
        echo "not installed"
    fi
}

git_repo() {
    echo $REPO_URL
}

if [[ "$1" == "install" ]]; then
    do_install
elif [[ "$1" == "uninstall" ]]; then
    do_uninstall
elif [[ "$1" == "installed" ]]; then
    echo $(is_installed)
elif [[ "$1" == "git_version" ]]; then
    echo $(git_version)
elif [[ "$1" == "git_repo" ]]; then
    echo $(git_repo)
fi
